LLVM_LIBC_FUNCTION(int, creat, (const char *path, int mode_flags)) {
  ErrorOr<int> fd =
      linux_syscalls::open(path, O_CREAT | O_WRONLY | O_TRUNC, mode_flags);

  if (!fd) {
    libc_errno = fd.error();
    return -1;
  }
  return fd.value();
}

